package main

import (
	"errors"
	"math"
)

var (
	errSyntax   = errors.New("syntax error")
	errDivZero  = errors.New("division by zero")
	errOverflow = errors.New("integer overflow")
)

// parser is a recursive-descent evaluator over a single expression line.
type parser struct {
	src []byte
	pos int
}

// Eval evaluates one expression according to the calc grammar.
func Eval(src []byte) (int64, error) {
	p := parser{src: src}
	v, err := p.expr()
	if err != nil {
		return 0, err
	}
	p.skipSpace()
	if p.pos != len(p.src) {
		return 0, errSyntax
	}
	return v, nil
}

func (p *parser) skipSpace() {
	for p.pos < len(p.src) && isSpace(p.src[p.pos]) {
		p.pos++
	}
}

// peek returns the next non-space byte, or 0 at end of input.
func (p *parser) peek() byte {
	p.skipSpace()
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}

func (p *parser) expr() (int64, error) {
	v, err := p.term()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '+' && op != '-' {
			return v, nil
		}
		p.pos++
		rhs, err := p.term()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			v, err = add(v, rhs)
		} else {
			v, err = sub(v, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

func (p *parser) term() (int64, error) {
	v, err := p.unary()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '*' && op != '/' && op != '%' {
			return v, nil
		}
		p.pos++
		rhs, err := p.unary()
		if err != nil {
			return 0, err
		}
		switch op {
		case '*':
			v, err = mul(v, rhs)
		case '/':
			v, err = div(v, rhs)
		default:
			v, err = rem(v, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

func (p *parser) unary() (int64, error) {
	// Count consecutive minus signs iteratively to avoid deep recursion.
	neg := 0
	for p.peek() == '-' {
		p.pos++
		neg++
	}
	v, err := p.primary()
	if err != nil {
		return 0, err
	}
	for ; neg > 0; neg-- {
		if v == math.MinInt64 {
			return 0, errOverflow
		}
		v = -v
	}
	return v, nil
}

func (p *parser) primary() (int64, error) {
	c := p.peek()
	switch {
	case c == '(':
		p.pos++
		v, err := p.expr()
		if err != nil {
			return 0, err
		}
		if p.peek() != ')' {
			return 0, errSyntax
		}
		p.pos++
		return v, nil
	case isDigit(c):
		return p.number()
	default:
		return 0, errSyntax
	}
}

func (p *parser) number() (int64, error) {
	var v int64
	overflow := false
	for p.pos < len(p.src) && isDigit(p.src[p.pos]) {
		d := int64(p.src[p.pos] - '0')
		if v > (math.MaxInt64-d)/10 {
			overflow = true
		} else {
			v = v*10 + d
		}
		p.pos++
	}
	if overflow {
		return 0, errOverflow
	}
	return v, nil
}

func isSpace(c byte) bool { return c == ' ' || c == '\t' }
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func add(a, b int64) (int64, error) {
	r := a + b
	if (b > 0 && r < a) || (b < 0 && r > a) {
		return 0, errOverflow
	}
	return r, nil
}

func sub(a, b int64) (int64, error) {
	r := a - b
	if (b > 0 && r > a) || (b < 0 && r < a) {
		return 0, errOverflow
	}
	return r, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	r := a * b
	if r/b != a || (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) {
		return 0, errOverflow
	}
	return r, nil
}

func div(a, b int64) (int64, error) {
	if b == 0 {
		return 0, errDivZero
	}
	if a == math.MinInt64 && b == -1 {
		return 0, errOverflow
	}
	return a / b, nil
}

func rem(a, b int64) (int64, error) {
	if b == 0 {
		return 0, errDivZero
	}
	if b == -1 {
		return 0, nil
	}
	return a % b, nil
}

package main

import (
	"strings"
	"testing"
)

func TestEval(t *testing.T) {
	tests := []struct {
		in   string
		want int64
		err  bool
	}{
		{in: "1 + 2 * 3", want: 7},
		{in: "-7 / 2", want: -3},
		{in: "-7 % 3", want: -1},
		{in: "7 % -3", want: 1},
		{in: "--5", want: 5},
		{in: "10 - 4 - 3", want: 3},
		{in: "(-9223372036854775807 - 1) % -1", want: 0},
		{in: "-9223372036854775807 - 1", want: -9223372036854775808},
		{in: "9223372036854775807", want: 9223372036854775807},
		{in: "007", want: 7},
		{in: "\t( 1 )\t", want: 1},
		{in: "-9223372036854775808", err: true},
		{in: "9223372036854775807 + 1", err: true},
		{in: "(-9223372036854775807 - 1) / -1", err: true},
		{in: "(-9223372036854775807 - 1) * -1", err: true},
		{in: "-(-9223372036854775807 - 1)", err: true},
		{in: "3037000500 * 3037000500", err: true},
		{in: "1 / 0", err: true},
		{in: "1 % 0", err: true},
		{in: "(1 + 2", err: true},
		{in: "1 + 2)", err: true},
		{in: "()", err: true},
		{in: "1 2", err: true},
		{in: "+1", err: true},
		{in: "1 +", err: true},
		{in: "1\r", err: true},
	}
	for _, tt := range tests {
		got, err := Eval([]byte(tt.in))
		if (err != nil) != tt.err || (!tt.err && got != tt.want) {
			t.Errorf("Eval(%q) = %d, %v; want %d, err=%v", tt.in, got, err, tt.want, tt.err)
		}
	}
}

func TestRun(t *testing.T) {
	var out strings.Builder
	if err := run(strings.NewReader("\n  42  \n\t\n1+1\n1/0"), &out); err != nil {
		t.Fatal(err)
	}
	if got, want := out.String(), "42\n2\nerror\n"; got != want {
		t.Errorf("run output = %q, want %q", got, want)
	}
}

func TestDeepNesting(t *testing.T) {
	const n = 100000
	src := strings.Repeat("(", n) + "1" + strings.Repeat(")", n)
	if v, err := Eval([]byte(src)); err != nil || v != 1 {
		t.Errorf("deep nesting: got %d, %v", v, err)
	}
}

// Command calc evaluates one 64-bit signed integer expression per input line.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "calc:", err)
	}
}

func run(r io.Reader, w io.Writer) error {
	in := bufio.NewReaderSize(r, 64*1024)
	out := bufio.NewWriterSize(w, 64*1024)
	var buf, num []byte
	for {
		line, err := in.ReadSlice('\n')
		if err == bufio.ErrBufferFull {
			// Long line: accumulate until the delimiter is found.
			buf = append(buf[:0], line...)
			for err == bufio.ErrBufferFull {
				line, err = in.ReadSlice('\n')
				buf = append(buf, line...)
			}
			line = buf
		}
		if err != nil && err != io.EOF {
			return err
		}
		line = bytes.TrimSuffix(line, []byte{'\n'})
		if len(bytes.Trim(line, " \t")) > 0 {
			if v, evalErr := Eval(line); evalErr != nil {
				out.WriteString("error\n")
			} else {
				num = strconv.AppendInt(num[:0], v, 10)
				out.Write(num)
				out.WriteByte('\n')
			}
		}
		if err == io.EOF {
			break
		}
	}
	return out.Flush()
}
